############################################  Using gamma distributions as priors ############################################# Two equivalent ways of parameterising a gamma distribution# First way# Gamma distribution is defined by two parameters - shape and rate.# Rate parameter is Beta# Shape parameter is Alpha # Mean of a gamma dist is Alpha / Beta# Second way # Gamma distribution is defined by two parameters - shape and scale.# Shape parameter is kappa, which is equivalent to Alpha# Scale parameter is theta, which is 1/beta. ## Below is using the first way.mean_t <- mean_G <- 65alpha1 <- 2beta1 <- alpha1/mean_t # ~0.03alpha2 <- 10beta2 <- alpha2/mean_t # ~0.15alpha3 <- 50beta3 <- alpha3/mean_t # ~0.77alpha4 <- 100beta4 <- alpha4/mean_t # ~1.54curve( dgamma( x, alpha4, beta4 ), from = 0, to = 300, col = "green" )curve( dgamma( x, alpha3, beta3 ), col = "blue", add = TRUE )curve( dgamma( x, alpha2, beta2 ), col = "purple", add = TRUE)curve( dgamma( x, alpha1, beta1 ), col = "black", add = TRUE )## Let the mean be the target for your estimated parameter## Then play with different values of alpha and beta to set how confident you are## You can have it quite a wide interval, or narrow depending on uncertainty.